}

.post-content th {
  font-weight: 600;
  color: var(--text);
  background: var(--bg-alt);
}

.post-content td {
  color: var(--text-muted);
}

.post-content tr:hover td {
  background: var(--bg-alt);
}

/* Lightbox */
.lightbox-overlay {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.9);
  z-index: 1000;
  cursor: pointer;
  justify-content: center;
  align-items: center;
}

.lightbox-overlay.active {
  display: flex;
}

.lightbox-overlay img {
  max-width: 90%;
  max-height: 90%;
  border-radius: 4px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

.lightbox-close {
  position: absolute;
  top: 1rem;
  right: 1.5rem;
  color: white;
  font-size: 2rem;
  cursor: pointer;
  opacity: 0.8;
  transition: opacity 0.2s;
}

.lightbox-close:hover {
  opacity: 1;
}

/* Blockquotes */
blockquote {
  margin: 1.5rem 0;
  padding: 1rem 1.5rem;
  border-left: 4px solid var(--accent);
  background: transparent;
}

blockquote p {
  font-style: normal;
  color: var(--text);
  margin-bottom: 0.5rem;
  line-height: 1.7;
}

blockquote p:last-child {
  margin-bottom: 0;
}

blockquote strong {
  font-style: normal;
  color: var(--text);
}

