/* ==========================================================================
   johnmclevey.com — site styles
   Design language: warm off-white ground, near-black ink, hairline rules,
   uppercase section labels, a single restrained blue for hover/focus.
   ========================================================================== */

:root {
  --bg: #fcfcfa;
  --ink: #191918;
  --body: #33322f;
  --muted: #5c5a54;
  --faint: #8a877f;
  --border: #e6e4de;
  --border-light: #f0efeb;
  --accent: #2a78d6;
  --surface: #f6f5f1;
  --font-sans: 'Instrument Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI',
    Helvetica, Arial, sans-serif;
  --font-mono: ui-monospace, 'SF Mono', SFMono-Regular, Menlo, Consolas, monospace;
}

/* Base ------------------------------------------------------------------- */

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

a {
  color: inherit;
}

a:hover {
  color: var(--accent);
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 2px;
}

img {
  max-width: 100%;
  height: auto;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  z-index: 200;
  background: var(--ink);
  color: var(--bg);
  padding: 10px 16px;
  text-decoration: none;
  font-size: 14px;
}

.skip-link:focus {
  left: 12px;
  top: 12px;
  color: var(--bg);
}

/* Layout ------------------------------------------------------------------ */

.container {
  max-width: 800px;
  margin: 0 auto;
  padding-left: 40px;
  padding-right: 40px;
}

.hero {
  padding-top: 72px;
}

.hero h1 {
  margin: 0;
  font-size: 34px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.lede {
  margin: 24px 0 0;
  font-size: 17px;
  line-height: 1.65;
  color: var(--body);
  text-wrap: pretty;
}

.section {
  margin-top: 64px;
}

.section-mid {
  margin-top: 56px;
}

.section-tight {
  margin-top: 48px;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 16px;
  border-top: 1px solid var(--border);
  padding-top: 20px;
}

.section-label {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--faint);
}

.section-link {
  font-size: 13px;
  color: var(--muted);
  text-decoration: none;
  flex: none;
}

.section-note {
  margin: 16px 0 0;
  font-size: 13.5px;
  color: var(--faint);
}

.section-note a {
  color: var(--muted);
}

/* Header ------------------------------------------------------------------ */

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 28px 64px;
  border-bottom: 1px solid var(--border);
  position: relative;
}

.brand {
  font-weight: 600;
  font-size: 15px;
  letter-spacing: -0.01em;
  text-decoration: none;
}

.site-nav {
  display: flex;
  gap: 28px;
  font-size: 13.5px;
  color: var(--muted);
}

.site-nav a {
  text-decoration: none;
  color: var(--muted);
}

.site-nav a:hover {
  color: var(--accent);
}

.site-nav a.active,
.site-nav a.nav-cv {
  color: var(--ink);
  font-weight: 500;
}

.nav-toggle {
  display: none;
  appearance: none;
  background: none;
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 8px 12px;
  font-family: inherit;
  font-size: 13px;
  color: var(--muted);
  cursor: pointer;
  align-items: center;
  gap: 8px;
}

.nav-toggle-bars {
  display: inline-flex;
  flex-direction: column;
  gap: 4px;
}

.nav-toggle-bars span {
  display: block;
  width: 14px;
  height: 1.5px;
  background: currentColor;
}

/* Footer ------------------------------------------------------------------ */

.site-footer {
  margin-top: 72px;
}

.footer-inner {
  border-top: 1px solid var(--border);
  padding: 24px 0 64px;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 13px;
  color: var(--faint);
}

.footer-contact {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
}

.footer-inner a {
  text-decoration: none;
  color: var(--faint);
}

.footer-inner a:hover {
  color: var(--accent);
}

/* Home: profile ------------------------------------------------------------ */

.profile {
  display: flex;
  gap: 36px;
  align-items: center;
}

.profile-img {
  width: 104px;
  height: 104px;
  border-radius: 50%;
  object-fit: cover;
  object-position: 50% 20%;
  flex: none;
}

.profile h1 {
  margin: 0 0 10px;
}

.profile-role {
  margin: 0;
  font-size: 15.5px;
  line-height: 1.5;
  color: var(--muted);
}

.intro p {
  margin: 20px 0 0;
  font-size: 17px;
  line-height: 1.65;
  color: var(--body);
  text-wrap: pretty;
}

.intro p:first-child {
  margin-top: 40px;
}

.social-row {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 22px;
  margin: 24px 0 0;
  padding: 0;
  font-size: 13.5px;
  color: var(--muted);
}

.social-row a {
  text-decoration: none;
}

/* Home: book grid ----------------------------------------------------------- */

.book-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 24px;
}

.book-card {
  display: flex;
  flex-direction: column;
  gap: 10px;
  text-decoration: none;
}

.book-card img {
  width: 100%;
  aspect-ratio: 2 / 3;
  object-fit: cover;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.12);
}

.book-card-title {
  font-size: 13px;
  line-height: 1.4;
  font-weight: 500;
}

.book-card-meta {
  font-size: 12px;
  color: var(--faint);
  margin-top: -6px;
}

/* Publication / post lists --------------------------------------------------- */

.pub-list {
  display: flex;
  flex-direction: column;
  margin-top: 8px;
}

.pub-item {
  padding: 16px 0;
  border-bottom: 1px solid var(--border-light);
}

.pub-item-roomy {
  padding: 20px 0;
}

.pub-item:last-child {
  border-bottom: none;
}

.pub-row {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: baseline;
}

.pub-title {
  font-size: 15.5px;
  font-weight: 500;
  text-decoration: none;
  line-height: 1.4;
}

.pub-venue {
  font-size: 13px;
  color: var(--faint);
  flex: none;
}

.pub-authors {
  font-size: 13.5px;
  color: var(--faint);
  margin-top: 6px;
}

/* Home: teaching grid --------------------------------------------------------- */

.course-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 24px;
}

.course-cell {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.course-code {
  font-size: 12px;
  color: var(--faint);
}

.course-name {
  font-size: 14.5px;
  font-weight: 500;
  line-height: 1.35;
}

/* Research: featured books ------------------------------------------------------ */

.book-features {
  display: flex;
  flex-direction: column;
  gap: 48px;
  margin-top: 32px;
}

.book-feature {
  display: grid;
  grid-template-columns: 160px 1fr;
  gap: 32px;
  align-items: start;
}

.book-feature-cover img {
  width: 100%;
  aspect-ratio: 2 / 3;
  object-fit: cover;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.14);
  display: block;
}

.book-feature h3 {
  margin: 0;
  font-size: 21px;
  font-weight: 600;
  letter-spacing: -0.015em;
  line-height: 1.25;
}

.book-feature h3 a {
  text-decoration: none;
}

.book-feature-meta {
  font-size: 13.5px;
  color: var(--faint);
  margin-top: 8px;
}

.book-feature p {
  margin: 14px 0 0;
  font-size: 15px;
  line-height: 1.6;
  color: var(--muted);
  text-wrap: pretty;
}

/* Teaching page ------------------------------------------------------------------ */

.course-entries {
  display: flex;
  flex-direction: column;
  gap: 36px;
  margin-top: 28px;
}

.course-kicker {
  font-size: 12.5px;
  color: var(--faint);
  letter-spacing: 0.03em;
  margin: 0;
}

.course-entry h3 {
  margin: 6px 0 0;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.015em;
  line-height: 1.3;
}

.course-entry p {
  margin: 10px 0 0;
  font-size: 15px;
  line-height: 1.6;
  color: var(--muted);
  max-width: 560px;
  text-wrap: pretty;
}

.more-link {
  display: inline-block;
  margin-top: 10px;
  font-size: 13.5px;
  color: var(--muted);
  text-decoration: none;
}

.supervision-note p {
  margin: 20px 0 0;
  font-size: 15px;
  line-height: 1.6;
  color: var(--muted);
  max-width: 560px;
  text-wrap: pretty;
}

.supervision-note a {
  color: var(--muted);
}

/* Blog ---------------------------------------------------------------------------- */

.blog-tagline {
  margin: 24px 0 0;
  font-size: 16px;
  line-height: 1.65;
  color: var(--muted);
  font-style: italic;
  max-width: 560px;
  text-wrap: pretty;
}

/* Article pages (posts, books, courses, CV) ----------------------------------------- */

.post-header {
  margin-bottom: 8px;
}

.post-header h1 {
  margin: 0;
  font-size: 30px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.15;
}

.post-meta {
  margin: 14px 0 0;
  font-size: 13.5px;
  color: var(--faint);
  line-height: 1.6;
}

.post-header .post-meta:first-child {
  margin: 0 0 12px;
}

.post-header .course-kicker {
  margin: 0 0 10px;
}

.back-link {
  display: inline-block;
  margin-top: 48px;
  font-size: 13.5px;
  color: var(--muted);
  text-decoration: none;
}

.book-page-header {
  display: grid;
  grid-template-columns: 160px 1fr;
  gap: 32px;
  align-items: center;
}

.book-page-header img {
  width: 100%;
  aspect-ratio: 2 / 3;
  object-fit: cover;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.14);
}

.book-page-header h1 {
  font-size: 27px;
}

.book-page-meta {
  margin: 14px 0 0;
  font-size: 14px;
  line-height: 1.6;
  color: var(--faint);
}

/* Prose: long-form content --------------------------------------------------------- */

.prose {
  margin-top: 28px;
}

.prose p,
.prose li {
  font-size: 16px;
  line-height: 1.7;
  color: var(--body);
  text-wrap: pretty;
}

.prose p {
  margin: 16px 0 0;
}

.prose ul,
.prose ol {
  margin: 16px 0 0;
  padding-left: 24px;
}

.prose li {
  margin-top: 6px;
}

.prose h2 {
  margin: 56px 0 0;
  border-top: 1px solid var(--border);
  padding-top: 20px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--faint);
}

.prose h3 {
  margin: 32px 0 0;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.3;
}

.prose h4 {
  margin: 24px 0 0;
  font-size: 15.5px;
  font-weight: 600;
  line-height: 1.35;
}

.prose blockquote {
  margin: 24px 0 0;
  padding: 2px 0 2px 20px;
  border-left: 2px solid var(--border);
}

.prose blockquote p {
  color: var(--muted);
}

.prose hr {
  border: none;
  border-top: 1px solid var(--border-light);
  margin: 40px 0;
}

.prose img {
  display: block;
  margin: 24px 0 0;
}

.prose a {
  color: var(--body);
  text-decoration-color: var(--border);
  text-underline-offset: 3px;
}

.prose a:hover {
  color: var(--accent);
  text-decoration-color: var(--accent);
}

.chapter-authors {
  font-size: 14px;
  color: var(--faint);
}

/* Prose: code ------------------------------------------------------------------------ */

.prose code {
  font-family: var(--font-mono);
  font-size: 0.86em;
  background: var(--border-light);
  padding: 0.12em 0.36em;
  border-radius: 3px;
}

.prose pre {
  margin: 20px 0 0;
  padding: 16px 18px;
  background: var(--surface);
  border: 1px solid var(--border-light);
  border-radius: 6px;
  overflow-x: auto;
  line-height: 1.55;
}

.prose pre code {
  background: none;
  padding: 0;
  font-size: 13.5px;
  border-radius: 0;
}

/* Override highlight.js background so code blocks sit on the site surface color */
.prose pre code.hljs {
  background: var(--surface);
  padding: 0;
}

.code-output {
  color: var(--muted);
  font-size: 13.5px;
}

/* Prose: tables ------------------------------------------------------------------------ */

.prose table {
  width: 100%;
  border-collapse: collapse;
  margin: 24px 0 0;
  font-size: 14px;
}

.prose th {
  text-align: left;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--faint);
  border-bottom: 1px solid var(--border);
  padding: 10px 16px 10px 0;
}

.prose td {
  border-bottom: 1px solid var(--border-light);
  padding: 10px 16px 10px 0;
  color: var(--body);
  vertical-align: top;
}

/* Lightbox ------------------------------------------------------------------------------ */

.post-content img {
  cursor: zoom-in;
}

.lightbox-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.9);
  z-index: 1000;
  cursor: pointer;
  justify-content: center;
  align-items: center;
}

.lightbox-overlay.active {
  display: flex;
}

.lightbox-overlay img {
  max-width: 90%;
  max-height: 90%;
  border-radius: 4px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

.lightbox-close {
  position: absolute;
  top: 16px;
  right: 24px;
  background: none;
  border: none;
  color: #fff;
  font-size: 32px;
  line-height: 1;
  cursor: pointer;
  opacity: 0.8;
}

.lightbox-close:hover {
  opacity: 1;
}

/* CV ------------------------------------------------------------------------------------- */

.cv-year-list {
  list-style: none;
  padding-left: 0;
}

.cv-year-list li {
  display: flex;
  gap: 20px;
  margin-top: 10px;
}

.cv-year-list .year {
  flex: none;
  width: 96px;
  font-size: 13.5px;
  color: var(--faint);
}

.cv-year-list .content {
  flex: 1;
}

.toc-sidebar {
  position: fixed;
  top: 132px;
  left: calc(50vw - 400px - 248px);
  width: 220px;
  max-height: calc(100vh - 180px);
  overflow-y: auto;
  font-size: 13px;
}

.toc-title {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--faint);
  margin-bottom: 12px;
}

.toc-sidebar ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.toc-sidebar li {
  margin: 0;
}

.toc-sidebar a {
  display: block;
  padding: 5px 10px;
  color: var(--muted);
  text-decoration: none;
  border-left: 1px solid var(--border-light);
  line-height: 1.4;
}

.toc-sidebar a:hover {
  color: var(--ink);
}

.toc-sidebar a.active {
  color: var(--ink);
  border-left-color: var(--ink);
  font-weight: 500;
}

@media (max-width: 1340px) {
  .toc-sidebar {
    display: none;
  }
}

/* Responsive ------------------------------------------------------------------------------ */

@media (max-width: 900px) {
  .site-header {
    padding: 22px 32px;
  }
}

@media (max-width: 720px) {
  .site-header {
    padding: 16px 24px;
  }

  .nav-toggle {
    display: inline-flex;
  }

  .site-nav {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    z-index: 100;
    flex-direction: column;
    gap: 0;
    background: var(--bg);
    border-bottom: 1px solid var(--border);
    padding: 8px 0 12px;
  }

  .site-nav.open {
    display: flex;
  }

  .site-nav a {
    padding: 12px 24px;
    font-size: 15px;
  }

  .container {
    padding-left: 24px;
    padding-right: 24px;
  }

  .hero {
    padding-top: 48px;
  }

  .hero h1 {
    font-size: 29px;
  }

  .section {
    margin-top: 48px;
  }

  .section-mid,
  .section-tight {
    margin-top: 40px;
  }

  .profile {
    gap: 24px;
  }

  .profile-img {
    width: 84px;
    height: 84px;
  }

  .book-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .course-grid {
    grid-template-columns: 1fr;
  }

  .pub-row {
    flex-direction: column;
    gap: 4px;
  }

  .book-feature {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .book-feature-cover {
    max-width: 150px;
  }

  .book-page-header {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .book-page-header img {
    max-width: 150px;
  }

  .cv-year-list li {
    flex-direction: column;
    gap: 2px;
  }

  .cv-year-list .year {
    width: auto;
  }

  .prose table {
    display: block;
    overflow-x: auto;
  }
}

@media (max-width: 420px) {
  .profile {
    flex-direction: column;
    align-items: flex-start;
    gap: 20px;
  }
}

