:root {
  --bg: #fff;
  --bg-alt: #fafafa;
  --text: #111;
  --text-muted: #666;
  --accent: #ff42a1;
  --border: #e5e5e5;
}

[data-theme="dark"] {
  --bg: #1e2129;
  --bg-alt: #262a33;
  --text: #D8DEE9;
  --text-muted: #a0a8b8;
  --accent: #00a1ff;
  --border: #3a3f4a;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 17px;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.7;
  min-height: 100vh;
  transition: background 0.2s, color 0.2s;
}

a {
  color: inherit;
  text-decoration: none;
}

/* Header */
header {
  padding: 2rem 2rem 0;
  max-width: 720px;
  margin: 0 auto;
}

nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.5rem;
  border-bottom: 1px solid var(--border);
  padding-bottom: 1rem;
}

nav a {
  color: var(--text-muted);
  font-size: 0.9rem;
  transition: color 0.2s;
}

nav a:hover,
nav a.active {
  color: var(--text);
}

nav a.nav-home {
  font-weight: 600;
  color: var(--text);
}

.theme-toggle {
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  margin-left: auto;
  display: flex;
  align-items: center;
}

.toggle-track {
  display: block;
  width: 32px;
  height: 18px;
  background: var(--text-muted);
  border-radius: 9px;
  position: relative;
  transition: background 0.2s;
}

.toggle-thumb {
  display: block;
  width: 14px;
  height: 14px;
  background: var(--bg);
  border-radius: 50%;
  position: absolute;
  top: 2px;
  left: 2px;
  transition: transform 0.2s;
}

[data-theme="dark"] .toggle-thumb {
  transform: translateX(14px);
}

.theme-toggle:hover .toggle-track {
  background: var(--text);
}

/* Main */
main {
  max-width: 720px;
  margin: 0 auto;
  padding: 3rem 2rem 6rem;
}

h1 {
  font-size: 2.2rem;
  font-weight: 300;
  letter-spacing: 0.03em;
  margin-bottom: 0.25rem;
  line-height: 1.2;
}

h1 .first-name {
  font-weight: 700;
}

h1 .last-name {
  font-weight: 300;
}

h2 {
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text);
  margin: 3rem 0 1rem;
}

h3 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
  color: var(--text);
}

p {
  color: var(--text-muted);
  margin-bottom: 1rem;
}

.intro {
