  padding: 0 !important;
  margin: 0 !important;
}

aside.toc-sidebar nav ul li {
  display: block;
  margin-bottom: 0;
  line-height: 1.4;
}

aside.toc-sidebar nav a {
  display: block;
  padding: 0.35rem 0 0.35rem 1rem;
  color: var(--text-muted);
  font-size: 0.85rem;
  border-left: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
  text-decoration: none;
}

aside.toc-sidebar nav a:hover {
  color: var(--text);
}

aside.toc-sidebar nav a.active {
  color: var(--accent);
  border-left-color: var(--accent);
}

/* Level 2 headings (h2) */
aside.toc-sidebar .toc-h2 > a {
  font-weight: 500;
}

/* Level 3 headings (h3) - indented */
aside.toc-sidebar .toc-h3 > a {
  padding-left: 1.75rem;
  font-size: 0.8rem;
}

/* Scrollbar styling for TOC */
aside.toc-sidebar::-webkit-scrollbar {
  width: 4px;
}

aside.toc-sidebar::-webkit-scrollbar-track {
  background: transparent;
}

aside.toc-sidebar::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 2px;
}

aside.toc-sidebar::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

/* Hide TOC on smaller screens */
@media (max-width: 1200px) {
  aside.toc-sidebar {
    display: none !important;
  }
}

/* Adjust TOC position for wider screens */
@media (min-width: 1400px) {
  aside.toc-sidebar {
    right: calc((100vw - 720px) / 2 - 280px);
  }
}

