"""Rough well-formedness pass and template-artifact scan over generated HTML."""
from html.parser import HTMLParser
from pathlib import Path

VOID = {"meta","link","img","br","hr","input","source","area","base","col","embed","track","wbr"}

class Checker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in VOID:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in VOID:
            return
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        elif tag in self.stack:
            while self.stack and self.stack[-1] != tag:
                self.errors.append(f"unclosed <{self.stack.pop()}>")
            self.stack.pop()
        else:
            self.errors.append(f"stray </{tag}>")

for page in sorted(Path("docs").rglob("*.html")):
    text = page.read_text()
    if "{{" in text or "{%" in text:
        print(f"TEMPLATE ARTIFACT in {page}")
    c = Checker()
    c.feed(text)
    c.close()
    leftover = [t for t in c.stack if t not in ("html","body")]
    if c.errors or leftover:
        print(f"{page}: errors={c.errors[:5]} unclosed={leftover[:8]}")
print("scan complete")
EOF

