"""Case-sensitive link check plus viewport meta check."""
import re
from pathlib import Path
from urllib.parse import urlparse, unquote

def exists_exact(path: Path) -> bool:
    current = Path("docs").resolve()
    try:
        rel = path.resolve().relative_to(current)
    except ValueError:
        return False
    for part in rel.parts:
        entries = {p.name for p in current.iterdir()}
        if part not in entries:
            return False
        current = current / part
    return True

problems = []
for page in Path("docs").rglob("*.html"):
    html = page.read_text()
    if 'name="viewport"' not in html:
        problems.append(f"{page}: missing viewport meta")
    for url in re.findall(r'(?:href|src)="([^"]+)"', html):
        p = urlparse(url)
        if p.scheme or url.startswith(("#", "mailto:")):
            continue
        target = page.parent / unquote(p.path)
        if not exists_exact(target):
            problems.append(f"{page}: case/missing {url}")

print("\n".join(problems) if problems else "case-sensitive links + viewport: all good")
EOF
